import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.D9ghT4bC.js";const b=JSON.parse('{"title":"轮询联机机制","description":"","frontmatter":{},"headers":[],"relativePath":"zh/UncivCN/Polling-multiplayer.md","filePath":"zh/UncivCN/Polling-multiplayer.md"}'),r={name:"zh/UncivCN/Polling-multiplayer.md"};function l(i,t,c,n,h,s){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="轮询联机机制" tabindex="-1">轮询联机机制 <a class="header-anchor" href="#轮询联机机制" aria-label="Permalink to &quot;轮询联机机制&quot;">​</a></h1><blockquote><p>作者：AutumnPizazz</p><p>完稿日期：2026 年 5 月 21 日</p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>轮询联机是 UncivCN 在原有动态回合机制之上新增的一种联机方式。原版联机采用严格顺序制：当前玩家操作完毕并点击&quot;下一回合&quot;后，经 AI 结算方可移交至下一位玩家，等待时长取决于对手操作速度。轮询联机将同一回合拆分为若干个时间片，存档在玩家之间按时间片轮流传递，从而将等待时间的上限从&quot;对手想多久就多久&quot;压缩为固定的数秒。</p><p>该机制为纯增量功能——不选轮询间隔则行为与原版完全一致，旧存档亦可正常加载。</p><h2 id="启用方式" tabindex="-1">启用方式 <a class="header-anchor" href="#启用方式" aria-label="Permalink to &quot;启用方式&quot;">​</a></h2><p>创建新游戏时，勾选 <strong>Online Multiplayer</strong>，其下方即出现 <strong>Polling interval</strong> 下拉框：</p><table tabindex="0"><thead><tr><th>选项</th><th>含义</th></tr></thead><tbody><tr><td>Off</td><td>关闭轮询，使用原版动态回合</td></tr><tr><td>5s / 10s / 15s / 20s / 30s</td><td>每轮每位玩家的操作窗口时长</td></tr></tbody></table><p>房主选择间隔后创建游戏，整局即进入轮询节奏。</p><h2 id="游戏流程" tabindex="-1">游戏流程 <a class="header-anchor" href="#游戏流程" aria-label="Permalink to &quot;游戏流程&quot;">​</a></h2><h3 id="回合内轮转" tabindex="-1">回合内轮转 <a class="header-anchor" href="#回合内轮转" aria-label="Permalink to &quot;回合内轮转&quot;">​</a></h3><p>游戏回合开始时，当前玩家获得一个操作窗口。窗口期内可正常操作单位和城市。窗口结束时：</p><ul><li><strong>玩家点击 &quot;I&#39;m done&quot;</strong>：标记该玩家本回合内不再需要操作，存档传给下一位未完成的玩家。该玩家本轮不再被轮询。</li><li><strong>计时器到期</strong>：存档自动传给下一位未完成的玩家，但不标记当前玩家完成。待轮转回来时仍可继续操作。</li><li><strong>仅剩一位玩家未完成</strong>：该玩家不再被切走，计时器反复重置，直至其主动点击 &quot;I&#39;m done&quot;。</li></ul><h3 id="回合推进" tabindex="-1">回合推进 <a class="header-anchor" href="#回合推进" aria-label="Permalink to &quot;回合推进&quot;">​</a></h3><p>当所有存活的人类玩家均已点击 &quot;I&#39;m done&quot;，回合正式推进：依次结束各人类玩家回合、处理所有 AI 文明、重置完成标记、为新回合的所有人类玩家开启新一轮轮转。</p><h3 id="倒计时显示" tabindex="-1">倒计时显示 <a class="header-anchor" href="#倒计时显示" aria-label="Permalink to &quot;倒计时显示&quot;">​</a></h3><p>顶栏回合数右侧会显示当前窗口的剩余秒数，颜色随剩余时间变化：</p><ul><li>绿色：剩余超过一半</li><li>金色：剩余 25% 至一半</li><li>珊瑚色：剩余不足 25%</li></ul><p>非自己回合或不处于轮询模式时，该位置不显示。</p><h2 id="技术实现" tabindex="-1">技术实现 <a class="header-anchor" href="#技术实现" aria-label="Permalink to &quot;技术实现&quot;">​</a></h2><h3 id="存档传递" tabindex="-1">存档传递 <a class="header-anchor" href="#存档传递" aria-label="Permalink to &quot;存档传递&quot;">​</a></h3><p>轮询联机沿用原版联机的上传/下载基础设施。每次窗口结束时，当前玩家将修改后的完整游戏状态上传至服务器，下一位玩家通过轮询或 WebSocket 推送检测到更新后下载。同一时刻仅一位玩家持操作权，无需处理合并冲突。</p><h3 id="websocket-推送" tabindex="-1">WebSocket 推送 <a class="header-anchor" href="#websocket-推送" aria-label="Permalink to &quot;WebSocket 推送&quot;">​</a></h3><p>为降低轮询延迟，客户端在进入轮询联机时自动建立 WebSocket 连接。玩家上传存档后，服务器即时推送 <code>GameUpdated</code> 消息至同房间所有在线客户端，触发对方立即下载最新状态。该机制复用现有的聊天 WebSocket 端点，无需额外配置。</p><h3 id="新增字段" tabindex="-1">新增字段 <a class="header-anchor" href="#新增字段" aria-label="Permalink to &quot;新增字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>位置</th><th>说明</th></tr></thead><tbody><tr><td><code>pollingIntervalSeconds</code></td><td><code>GameParameters</code></td><td>轮询间隔秒数，0 表示关闭</td></tr><tr><td><code>playersFinishedThisTurn</code></td><td><code>GameInfo</code></td><td>本回合已确认完成的文明 ID 集合</td></tr></tbody></table><h3 id="服务端改动" tabindex="-1">服务端改动 <a class="header-anchor" href="#服务端改动" aria-label="Permalink to &quot;服务端改动&quot;">​</a></h3><p>服务端 <code>Response</code> 类型新增 <code>GameUpdated</code> 消息，文件上传成功后向该房间的所有 WebSocket 订阅者广播。</p><h3 id="相关文件" tabindex="-1">相关文件 <a class="header-anchor" href="#相关文件" aria-label="Permalink to &quot;相关文件&quot;">​</a></h3><p>核心逻辑涉及以下源文件：</p><table tabindex="0"><thead><tr><th>文件</th><th>角色</th></tr></thead><tbody><tr><td><code>GameParameters.kt</code></td><td>新增 <code>pollingIntervalSeconds</code> 字段</td></tr><tr><td><code>GameInfo.kt</code></td><td>新增 <code>playersFinishedThisTurn</code> 集合、<code>nextTurnPolling()</code> 方法及辅助查询</td></tr><tr><td><code>NextTurnAction.kt</code></td><td>新增 <code>FinishAction</code> 枚举值</td></tr><tr><td><code>NextTurnButton.kt</code></td><td>轮询模式下按钮文本追加倒计时</td></tr><tr><td><code>WorldScreen.kt</code></td><td>新增计时器协程、<code>finishPollingTurn()</code> / <code>passPollingTurn()</code> 方法</td></tr><tr><td><code>WorldScreenTopBarResources.kt</code></td><td>顶栏倒计时显示</td></tr><tr><td><code>GameOptionsTable.kt</code></td><td>房间创建界面的轮询间隔选择器</td></tr><tr><td><code>Multiplayer.kt</code></td><td><code>GameInfoPreview.isUsersTurn()</code> 空值安全修复</td></tr><tr><td><code>MultiplayerGamePreview.kt</code></td><td><code>GameInfoPreview.getCurrentPlayerCiv()</code> 空值安全修复</td></tr><tr><td><code>ChatWebSocket.kt</code></td><td>客户端 <code>GameUpdated</code> 消息接收与刷新触发</td></tr><tr><td><code>UncivServer.kt</code></td><td>服务端文件上传后 WebSocket 广播</td></tr><tr><td><code>GameSettings.kt</code></td><td>默认密码设为 123456</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>参与轮询联机的所有玩家须在游戏设置中配置联机密码（默认 123456），否则 WebSocket 认证失败将影响推送功能。</li><li>轮询间隔建议根据玩家人数调整：2 人局 5~10 秒，4 人及以上建议 15 秒以上。</li><li>服务端须启用 <code>-chat</code> 选项（默认开启）以支持 WebSocket 推送。</li></ul>',33)])])}const p=e(r,[["render",l]]);export{b as __pageData,p as default};
